// DESPUÉS: el despacho publica lo que pasó; cada interesado se suscribe por su cuenta.
function crearEmisor() {
  const oyentes = new Map();
  return {
    suscribir(evento, fn) {
      const lista = oyentes.get(evento) ?? new Set();
      lista.add(fn);
      oyentes.set(evento, lista);
      return () => lista.delete(fn); // devuelve la forma de darse de baja
    },
    publicar(evento, dato) {
      for (const fn of [...(oyentes.get(evento) ?? [])]) {
        try { fn(dato); } catch (e) { console.log('  un oyente falló:', e.message); }
      }
    },
    cuantos: (evento) => oyentes.get(evento)?.size ?? 0,
  };
}
const bus = crearEmisor();
const log = [];
bus.suscribir('despachado', (d) => log.push(`SMS a cliente de ${d.id}`));
bus.suscribir('despachado', (d) => { throw new Error('el servicio de facturas no responde'); });
const bajaTablero = bus.suscribir('despachado', (d) => log.push(`tablero: ${d.id} en ruta`));
bus.suscribir('despachado', (d) => log.push(`depósito avisado por ${d.id}`)); // oyente nuevo: no se tocó despachar

bus.publicar('despachado', { id: 'D-102' });
console.log('DESPUÉS ->', log.join(' | '));

