// ANTES: un if por cada forma de cobrar. Agregar una obliga a tocar esta función.
function tarifaAntes(tipo, p) {
  if (tipo === 'por_kilo') return p.kg * 900;
  if (tipo === 'por_zona') return { caba: 3500, gba: 5200, interior: 8900 }[p.zona];
  if (tipo === 'por_volumen') return Math.ceil((p.largo * p.ancho * p.alto) / 5000) * 900;
  throw new Error('tipo de tarifa desconocido: ' + tipo);
}

// DESPUÉS: cada forma de cobrar es una función con la misma firma; quien cotiza recibe la que le toque.
