// Una hoja de ruta con bultos. Cada cambio es un objeto-comando: sabe hacerse y sabe deshacerse.
const ruta = { camioneta: [], pendientes: ['B1', 'B2', 'B3', 'B4'] };

const cargar = (bulto) => ({
  descripcion: `cargar ${bulto}`,
  hacer: () => { ruta.pendientes = ruta.pendientes.filter((b) => b !== bulto); ruta.camioneta.push(bulto); },
  deshacer: () => { ruta.camioneta = ruta.camioneta.filter((b) => b !== bulto); ruta.pendientes.push(bulto); },
});
const reordenar = (de, a) => ({
  descripcion: `mover posición ${de} a ${a}`,
  hacer: () => { const [x] = ruta.camioneta.splice(de, 1); ruta.camioneta.splice(a, 0, x); },
  deshacer: () => { const [x] = ruta.camioneta.splice(a, 1); ruta.camioneta.splice(de, 0, x); },
});

const historial = []; // lo ya ejecutado, en orden
const ejecutar = (cmd) => { cmd.hacer(); historial.push(cmd); };
const deshacerUltimo = () => { const c = historial.pop(); if (c) { c.deshacer(); console.log('  deshice:', c.descripcion); } };
const ver = (t) => console.log(t.padEnd(22), 'camioneta:', ruta.camioneta.join(','), '| pendientes:', ruta.pendientes.join(','));

ejecutar(cargar('B1')); ejecutar(cargar('B2')); ejecutar(cargar('B3'));
ver('tras 3 cargas');
ejecutar(reordenar(2, 0));
