// La máquina: una tabla de «desde este estado, con este evento, voy a aquel».
const TABLA = {
  creado:    { armar: 'armado', cancelar: 'cancelado' },
  armado:    { salir: 'en_ruta', cancelar: 'cancelado' },
  en_ruta:   { entregar: 'entregado', fallar: 'fallido' },
  fallido:   { reintentar: 'en_ruta', devolver: 'devuelto' },
  entregado: {}, cancelado: {}, devuelto: {},
};
const estados = Object.keys(TABLA);
const validas = estados.reduce((n, e) => n + Object.keys(TABLA[e]).length, 0);
console.log(`${estados.length} estados, ${validas} transiciones permitidas de ${estados.length * estados.length} pares posibles`);

class ErrorTransicion extends Error {}
function crearDespacho(id) {
  let estado = 'creado';
  const historia = [];
  return {
    get estado() { return estado; },
    historia,
    enviar(evento) {
      const destino = TABLA[estado][evento];
      if (!destino) throw new ErrorTransicion(`${id}: no se puede «${evento}» estando ${estado}`);
      historia.push(`${estado} --${evento}--> ${destino}`);
      estado = destino;
    },
  };
}

const d = crearDespacho('D-201');
for (const ev of ['armar', 'salir', 'fallar', 'reintentar', 'entregar']) d.enviar(ev);
console.log(d.historia.join('\n'));
try { d.enviar('cancelar'); } catch (e) { console.log('rechazado:', e.message); }

// Estados desde los que NO se puede llegar a uno final: un chequeo que la tabla permite y las banderas no.
const finales = estados.filter((e) => Object.keys(TABLA[e]).length === 0);
const llegaAFinal = (e, vistos = new Set()) => finales.includes(e) || (!vistos.has(e) && (vistos.add(e), Object.values(TABLA[e]).some((s) => llegaAFinal(s, vistos))));
console.log('finales:', finales.join(', '), '| estados sin salida posible:', estados.filter((e) => !llegaAFinal(e)).length);
